<template>
  <div class="full-width">
    <q-input
      v-model="searchInput"
      class="q-pt-md q-pb-md"
      dense
      autofocus
      :label="$t('search')"
      outlined
    />
  </div>
  <div class="full-width" v-if="filteredFields.length > 0">
    <draggable
      :list="filteredFields"
      class="dragArea row"
      :group="{ name: 'formbuilder', pull: 'clone', put: false }"
      :sort="false"
      item-key="name"
    >
      <template v-for="row in filteredFields" :key="row">
        <div
          class="col-sm-12 col-md-12 col-lg-12 q-pa-sm cursor-pointer mt-5 border-radius-5px"
          :class="row.is_hidden || row.isHidden ? 'hidden-field' : ''"
        >
          <div class="row">
            <div class="width-20px">
              <Icon icon="mdi:format-text" width="14" height="14" class="q-mr-sm" :class="row.is_hidden || row.isHidden ? 'icon-grayed' : ''" />
            </div>
            <div class="width-100-20px">
              <div class="full-width" :class="row.is_hidden || row.isHidden ? 'text-grey-6' : ''">
                {{ row.title }}
                <q-icon
                  v-if="row.is_hidden || row.isHidden"
                  name="visibility_off"
                  size="xs"
                  color="grey-6"
                  class="q-ml-xs"
                >
                  <q-tooltip>{{ $t('field_is_hidden') }}</q-tooltip>
                </q-icon>
              </div>
              <div class="full-width text-grey-6">
                {{ ' (' + row.field_name + ')' }}
              </div>
            </div>
          </div>
        </div>
      </template>
    </draggable>
  </div>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { VueDraggableNext } from 'vue-draggable-next';
import helperMixin from 'src/mixins/helperMixin';
import { listOfValuesApiService } from 'src/services';
import { storeToRefs } from 'pinia';
import { useSupplierLayoutsStore } from 'src/store/main';

export default defineComponent({
  name: 'FieldList',
  mixins: [helperMixin],
  components: {
    
    draggable: VueDraggableNext,
  },
  data() {
    return {
      searchInput: '',
    };
  },
  async mounted() {
    if (this.defaultFields.length === 0) {
      await this.getFields();
    }
  },
  unmounted(){
    this.searchInput = ''; 
    for (let field of this.defaultFields) {
      field.isSearched = true;
    }
  },
  watch: {
    searchInput(val) {
      for (let field of this.defaultFields) {
        if (val === '' || val == null) {
          field.isSearched = true;
        } else {
          field.isSearched = field.title
            .toLowerCase()
            .includes(val.toLowerCase());
        }
      }
    },
  },
  computed: {
    filteredFields() {
       
      return this.defaultFields.filter(
        (element: any) => element.isSearched as boolean,
      );
    },
  },
  methods: {},
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const {
      defaultFields,
      listOfValues
    } = storeToRefs(supplier_layouts_store);
    const { getDetaultFields, getFields } = supplier_layouts_store;
    return {
      fields: ref([] as dynamicObj[]),
      getDetaultFields,
      getFields,
      listOfValuesApiService,
      listOfValues,
      defaultFields,
    };
  },
});
</script>
