<template>
  <q-editor
    ref="editor"
    :toolbar="[
      ['left', 'center', 'right', 'justify', 'anchor'],
      ['bold', 'italic', 'underline', 'strike'],
      ['undo', 'redo'],
    ]"
    v-model="editor_value"
    @update:model-value="updateValue"
    :definitions="{
      anchor: {
        icon: 'link',
        handler: addAnchor,
      },
    }"
  />
  <q-dialog v-model="anchorModel">
    <q-card style="width: 300px; max-width: 80vw">
      <q-card-section>
        <div class="text-h6">Link</div>
      </q-card-section>

      <q-card-section class="q-pt-none">
        <q-input outlined dense v-model="anchorObject.url" label="URL" />
        <q-input
          class="q-mt-md"
          outlined
          dense
          v-model="anchorObject.text"
          label="Text"
        />
        <q-select
          class="q-mt-md"
          outlined
          dense
          v-model="anchorObject.target"
          :options="target"
          emit-value
          map-options
        />
      </q-card-section>

      <q-card-actions align="right">
        <q-btn flat :label="$t('cancel')" color="primary" v-close-popup />
        <q-btn
          flat
          :label="$t('confirm')"
          color="primary"
          @click="confirmAnchorTag"
          v-close-popup
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>
<script lang="ts">
import { QEditor } from 'quasar';
import { defineComponent, Ref, ref } from 'vue';

export default defineComponent({
  name: 'Editor',
  mixins: [],
  props: {
    value: {
      type: String,
      required: true,
    },
  },
  mounted() {
    this.editor_value = this.value ? this.value : '';
  },
  updated() {
    this.editor_value = this.value ? this.value : '';
  },
  data() {
    return {
      anchorModel: false,
      anchorObject: {
        url: '',
        text: '',
        target: '_self',
      },
      editor_value: '',
      target: [
        { label: 'Self', value: '_self' },
        { label: 'Blank', value: '_blank' },
        { label: 'Parent', value: '_parent' },
        { label: 'Top', value: '_top' },
      ],
    };
  },
  methods: {
    addAnchor() {
      this.anchorModel = true;
    },
    confirmAnchorTag() {
      const element = `<a class="text-primary" href="${this.anchorObject.url}" target="${this.anchorObject.target}">${this.anchorObject.text}</a>`;
      this.editor_value += element;
      this.$emit('update:value', this.editor_value);
    },
    updateValue() {
      this.$emit('update:value', this.editor_value);
    },
  },
  setup() {
    const editor = ref() as Ref<QEditor>;
    return {
      editor,
    };
  },
});
</script>
