<template>
  <div class="full-width" v-if="filteredFields.length > 0">
    <draggable
      :list="filteredFields"
      class="dragArea row"
      :group="{ name: 'formbuilder', pull: 'clone', put: false }"
      :sort="false"
      item-key="name"
    >
      <template v-for="(element, index) in filteredFields" :key="index">
        <div
          class="col-sm-12 col-md-12 col-lg-12 q-pa-sm cursor-pointer mt-5 border-radius-5px"
        >
          <div class="row">
            <Icon :icon="element.icon" width="14" height="14" class="q-mr-sm" />
            <div class="">{{ element.text }}</div>
          </div>
        </div>
      </template>
    </draggable>
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { FormBuilder } from './formbuilder.js';
import type { dynamicObj } from 'src/pages/assets';
import { VueDraggableNext } from 'vue-draggable-next';

export default defineComponent({
  name: 'Elements',
  components: {
    
    draggable: VueDraggableNext,
  },
  data() {
    return {
      fields: ref(FormBuilder.data().fields),
      dropElementOptions: FormBuilder.data().dropElementOptions,
    };
  },
  mounted() {
    this.init();
  },
  methods: {
    init() {
      this.filteredFields = this.fields.filter((field: any) => {
        return (
          field.hide_in_panel_list == false ||
          field.hide_in_panel_list == undefined
        );
      });
    },
  },
  setup() {
    return {
      filteredFields: ref([] as dynamicObj[]),
    };
  },
});
</script>
