<template>
  <div class="row items-center q-pb-xs">
    <q-space />
    <f-btn
      appearance="cancel"
      class="q-mr-sm"
      :label="$t('cancel')"
      @click="cancel"
    />
    <f-btn class="q-mr-sm" :label="$t('save')" @click="saveForm()" />
    <f-btn :label="$t('use_default_template')" @click="useDefualtTemplate"/>
  </div>
  <div class="container-wrapper row q-pb-md">
    <div class="col-xs-12 col-sm-4 col-md-3 col-lg-3 q-pt-sm full-height">
      <div class="full-width scroll-area-height scrolle-y">
        <div class="full-width" style="position: relative">
          <q-tabs
            v-model="activeTab"
            dense
            active-class="highlighted-back"
            indicator-color="primary"
            active-color="primary"
            align="justify"
          >
            <q-tab name="form_elements" :label="$t('elements')" />
            <q-tab
              name="element_properties"
              :label="$t('properties')"
            />
          </q-tabs>

          <q-separator />

          <q-tab-panels v-model="activeTab" animated>
            <q-tab-panel name="form_elements">
              <q-expansion-item
                expand-separator
                :label="$t('form_elements')"
                group="fieldsGroup"
                class="q-mb-md"
                header-class="text-weight-bold rounded-borders solid-border-1px"
              >
                <Elements />
              </q-expansion-item>
              <!-- <q-separator /> -->
              <q-expansion-item
                expand-separator
                :label="$t('fields')"
                group="fieldsGroup"
                header-class="text-weight-bold rounded-borders solid-border-1px"
              >
                <FieldForm />
              </q-expansion-item>
            </q-tab-panel>

            <q-tab-panel name="element_properties">
              <Properties :key="keyToUpdateComponnets" v-if="renderComponent" />
            </q-tab-panel>
          </q-tab-panels>
        </div>
      </div>
    </div>
    <div class="col-xs-12 col-sm-8 col-md-9 col-lg-9 padding-8-0-8-8">
      <div class="full-width">
        <FieldDesigner :isPanelSection="false" />
      </div>
    </div>
  </div>
  <q-inner-loading :showing="loading" style="z-index: 2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useSupplierLayoutsStore } from 'src/store/main';
import FieldDesigner from 'src/pages/Settings/SupplierLayouts/FieldDesigner.vue';
import Elements from 'src/pages/Settings/SupplierLayouts/Elements.vue';
import Properties from 'src/pages/Settings/SupplierLayouts/Properties.vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { supplierApiService } from 'src/services';
import FieldForm from 'src/pages/Settings/SupplierLayouts/FieldList.vue';
import helperUtil from 'src/utils/helperUtil';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin, helperUtil],
  components: {
    FieldDesigner,
    Elements,
    Properties,
    FieldForm,
  },
  mounted() {
    this.renderComponent = true;
    this.isDefaultFieldLoaded = true;
    this.formLayout = [];
    this.init();
  },
  unmounted: function () {
    this.model = {};
    this.activeTab = 'form_elements';
    this.defaultFields = [];
  },
  watch: {},
  data() {
    return {
      layout_type: this.$route.params.layout_type as string,
    };
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const {
      activeTab,
      defaultGroups,
      defaultFields,
      formLayout,
      renderComponent,
      isDefaultFieldLoaded,
      keyToUpdateComponnets,
      loading,
      model,
      isChangeDetected,
    } = storeToRefs(supplier_layouts_store);
    const {
      getSuppierLayoutByID,
      applyDefaultTemplate,
      getSupplierLayoutForBuilder,
      syncPropertiesFields,
    } = supplier_layouts_store;
    return {
      activeTab,
      defaultGroups,
      defaultFields,
      formLayout,
      renderComponent,
      isDefaultFieldLoaded,
      keyToUpdateComponnets,
      loading,
      model,
      isChangeDetected,
      syncPropertiesFields,
      getSuppierLayoutByID,
      applyDefaultTemplate,
      getSupplierLayoutForBuilder,
    };
  },
  methods: {
    cancel() {
      this.$router.push('/settings/supplier/layouts-builder');
    },
    validateGroup() {
      let is_valid = true;
      this.formLayout.map((group: any) => {
        if (!group.name || group.name === '' || group.name === null) {
          notify.error(this.$t('group_name_required'));
          is_valid = false;
        } else if (this.hasWhiteSpace(group.name)) {
          is_valid = false;
          notify.error(this.$t('SPACES_NOT_ALLOWED'));
        } else if (this.checkFirstLetterIsSpecialOrNumber(group.name)) {
          is_valid = false;
          notify.error(
            this.$t('errors_special_letter_number_not_allowed'),
          );
        } else if (!group.title || group.title === '' || group.title === null) {
          is_valid = false;
          notify.error(this.$t('translate_key_required'));
        }
      });
      return is_valid;
    },
    async saveForm() {
      if (!this.validateGroup()) {
        return;
      }
      if (this.isChangeDetected) {
        this.syncPropertiesFields(this.formLayout);
      }
      this.loading = true;
      const json = JSON.stringify(this.formLayout);
      const data = {
        title: this.layout_type,
        layout_type: this.layout_type.toLowerCase(),
        layout_json: json,
      } as dynamicObj;
      try {
        const response =
          await supplierApiService.createSupplierLayoutForm(data);
        await this.getSupplierLayoutForBuilder(this.layout_type.toLowerCase());
        if (response.success === false) {
          notify.error(response.message);
        } else {
          notify.success(this.$t('template_success_saved'));
        }
      } catch (err: any) {
        logError(err);
      } finally {
        this.loading = false;
        this.renderComponent = true;
      }
    },
    async useDefualtTemplate() {
      const layoutID = this.layout_type.toLowerCase();
      try {
        await this.applyDefaultTemplate(layoutID);
      } catch (error: any) {
        notify.error(error?.message);
      }
    },
    async init() {
      this.loading = true;
      try {
        await this.getSupplierLayoutForBuilder(this.layout_type.toLowerCase());
      } catch (err: any) {
        logError(err);
      } finally {
        this.loading = false;
      }
      if (this.isChangeDetected) {
        notify.warning(this.$t('field_setting_changes_message'));
      }
    },
  },
});
</script>
<style lang="scss" scoped>
:deep(.q-tab-panel) {
  padding: 16px;
}
</style>
