                onChangeProperties(val, 'required');
              }
            "
          />
        </div>

        <div class="row col-12 q-pa-xs">
          <span class="col-7 q-pt-sm">{{ $t('readonly') }}</span>
          <f-toggle
            class="col-4"
            size="xs"
            v-model="model['readonly']"
            @update:model-value="
              (val: any) => {
                onChangeProperties(val, 'readonly');
              }
            "
          />
        </div>
      </div>
      <q-separator v-if="model['type'] !== NOTE" />

      <!-- **********style********** -->
      <div class="row q-my-md">
        <div
          class="row col-12 q-pa-xs"
          v-if="model['type'] !== NOTE && model['type'] !== RADIO"
        >
          <span class="col-7 q-pt-sm">{{ $t('label_inner') }}</span>
          <f-toggle
            class="col-4"
            size="xs"
            :model-value="model['label_style'] === 'inner'"
            @update:model-value="
              (val: any) => {
                lableSetting(val);
              }
            "
          />
        </div>
        <div class="col-12 q-pa-xs" v-if="model['type'] !== NOTE">
          <span class="col-12 q-pt-sm">{{ $t('style_design') }}</span>
          <q-select
            outlined
            dense
            v-model="model['design']"
            :options="InputDesign"
            emit-value
            map-options
            @update:model-value="
              (val: any) => {
                onChangeProperties(val, 'design');
              }
            "
          >
          </q-select>
        </div>
      </div>
      <q-separator v-if="model['type'] !== NOTE" />
      <!-- <template> -->
      <div class="row q-my-md">
        <div class="col-6 q-pa-xs">
          <span class="col-12 q-pt-sm">{{ $t('type') }}</span>
          <q-input outlined dense v-model="model['type']" :readonly="true">
          </q-input>
        </div>
        <div
          class="col-6 q-pa-xs"
          v-if="
            (model['type'] === SELECT ||
              model['type'] === SEARCH ||
              model['type'] === RADIO) &&
            model['options']
          "
        >
          <span class="col-12 q-pt-sm">{{ $t('default_option') }}</span>
          <q-select
            outlined
            dense
            v-model="model['default_value']"
            :options="model['options']"
            emit-value
            map-options
            @update:model-value="
              (val: any) => {
                onChangeProperties(val, 'default_value');
              }
            "
          >
            <template v-slot:append v-if="model['default_value']">
              <q-icon
                name="close"
                @click.stop="model['default_value'] = ''"
                class="cursor-pointer"
              />
            </template>
          </q-select>
        </div>
        <div class="col-12 q-pa-xs" v-if="model['type'] === NOTE">
          <span class="col-12 q-pt-sm">{{ $t('Note') }}</span>
          <div>
            <form
              autocorrect="off"
              autocapitalize="off"
              autocomplete="off"
              spellcheck="false"
            >
              <Editor
                :value="model['default_value']"
                @update:value="
                  (val: string) => {
                    onChangeProperties(val, 'default_value');
                  }
                "
              />
            </form>
          </div>
        </div>
      </div>
      <q-separator />
      <!-- </template> -->

      <div class="row q-my-md">
        <div class="col-6 q-pa-xs">
          <span class="col-12 q-pt-sm">{{ $t('field_name') }}</span>
          <q-input
            outlined
            dense
            :readonly="model['is_default']"
            v-model="model['field_name']"
            :placeholder="$t('field_name')"
            @update:model-value="
              (val: any) => {
                onChangeProperties(val, 'field_name');
              }
            "
          />
        </div>
        <div v-if="model['type'] !== NOTE" class="col-6 q-pa-xs">
          <span class="col-12 q-pt-sm">{{ $t('label') }}</span>
          <q-input
            outlined
            dense
            :readonly="model['is_default']"
            v-model="model['title']"
            :placeholder="$t('label')"
            @update:model-value="
              (val: any) => {
                onChangeProperties(val, 'title');
              }
            "
          />
        </div>
        <div class="col-6 q-pa-xs">
          <span class="col-12 q-pt-sm">{{ $t('field_width') }}</span>
          <q-select
            outlined
            dense
            v-model="model['class']"
            :options="grid_class"
            emit-value
            map-options
            @update:model-value="
              (val: any) => {
                onChangeProperties(val, 'class');
              }
            "
          ></q-select>
        </div>
        <div
          v-if="model['type'] !== NOTE && model['type'] !== RADIO"
          class="col-6 q-pa-xs"
