          <span class="col-12 q-pt-sm">{{ $t('add_hint') }}</span>
          <q-input
            outlined
            dense
            v-model="model['labelHint']"
            :placeholder="$t('label_hint')"
            :required="true"
            @update:model-value="
              (val: any) => {
                onChangeProperties(val, 'labelHint');
              }
            "
          />
        </div>
      </div>
    </template>
  </template>
</template>
<script lang="ts">
import { storeToRefs } from 'pinia';
import copyUtil from 'src/utils/copyUtil';
import { defineComponent, reactive, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import keyDownHelper from 'src/pages/MediOrder/components/keyboard/keyDownHelper';
import { useSupplierLayoutsStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { formLayoutInputTypes } from 'src/pages/Settings/SupplierLayouts/formBuilderConstants.js';
import Editor from './component/Editor.vue';
import EdiIcon from 'src/pages/Settings/SupplierLayouts/component/EdiIcon.vue';
import { supplier_statuses } from 'src/constants';
import { useSettingStore } from 'src/store/main';

export default defineComponent({
  name: 'Properties',
  mixins: [helperUtil, keyDownHelper, copyUtil],
  components: {
    Editor,
    EdiIcon,
  },
  data() {
    return {
      rowIndex: ref(0),
      columnIndex: ref(0),
      isColumnMode: ref(true),
      selectedInput: ref(''),
      SELECT: formLayoutInputTypes.SELECT,
      SEARCH: formLayoutInputTypes.SEARCH,
      RADIO: formLayoutInputTypes.RADIO,
      NOTE: formLayoutInputTypes.NOTE,
      field_type_option: [
        {
          value: formLayoutInputTypes.STRING,
          label: this.$t('textbox'),
        },
        {
          value: formLayoutInputTypes.TEXTAREA,
          label: this.$t('textarea'),
        },
        {
          value: formLayoutInputTypes.NUMBER,
          label: this.$t('number'),
        },
        {
          value: formLayoutInputTypes.SELECT,
          label: this.$t('select'),
        },
        {
          value: formLayoutInputTypes.SEARCH,
          label: this.$t('select_with_search'),
        },
        {
          value: formLayoutInputTypes.FILE,
          label: this.$t('file'),
        },
        {
          value: formLayoutInputTypes.BOOLEAN,
          label: this.$t('boolean'),
        },
      ] as dynamicObj[],
      grid_class: [
        {
          label: 12,
          value: 'col-12',
        },
        {
          label: 11,
          value: 'col-11',
        },
        {
          label: 10,
          value: 'col-10',
        },
        {
          label: 9,
          value: 'col-9',
        },
        {
          label: 8,
          value: 'col-8',
        },
        {
          label: 7,
          value: 'col-7',
        },
        {
          label: 6,
          value: 'col-6',
        },
        {
          label: 5,
          value: 'col-5',
        },
        {
          label: 4,
          value: 'col-4',
        },
        {
          label: 3,
          value: 'col-3',
        },
        {
          label: 2,
          value: 'col-2',
        },
      ],
      iconOptions: [
        {
          value: 'person',
          label: 'Person',
        },
        {
          value: 'map',
          label: 'Map',
        },
        {
          value: 'contacts',
          label: 'Contacts',
        },
        {
          value: 'account_balance',
          label: 'Account Balance',
        },
        {
          value: 'shopping_cart',
          label: 'Shopping Cart',
        },
        {
          value: 'upload',
          label: 'Upload',
        },
        {
          value: 'edi',
          label: 'EDI',
        },
      ],
      InputDesign: [
        {
          value: 'filled',
          label: 'Filled',
        },
        {
          value: 'outlined',
          label: 'Outlined',
        },
        {
          value: 'standout',
          label: 'Standout',
        },
        {
          value: 'borderless',
          label: 'Borderless',
        },
        {
          value: 'outlined-filled',
          label: 'Outlined-Filled',
        },
      ],
      exiting_shortcut_keys: [] as string[],
    };
  },
  computed: {},
  watch: {},
  mounted: function () {
    if (this.model['field_name'] == 'status') {
      this.model['options'] = JSON.parse(
        this.user_settings[this.supplier_statuses],
      );
    }
  },
  // unmounted: function () {

  // },
  methods: {
    lableSetting(e: boolean) {
      if (e === true) {
        this.onChangeProperties('inner', 'label_style');
      } else {
        this.onChangeProperties('outer', 'label_style');
      }
    },
    onChangeProperties(e: any, propertiesField: string) {
      if (this.activeGroupIndex !== null) {
        // Get the active group
        let activeGroup = this.formLayout[this.activeGroupIndex];

        // Find the row with the matching name and update its label
        let rowToUpdate = activeGroup.rows.find(
          (row: any) => row.name === this.activeFieldName,
        );

        if (rowToUpdate) {
          rowToUpdate[propertiesField] = e;
          this.model[propertiesField] = e;
          if (propertiesField === 'options') {
            rowToUpdate['default_value'] = '';
          }
        }
      }
    },
    onChangePropertiesGroup(e: any, propertiesField: string) {
      if (this.activeGroupIndex !== null) {
        // Get the active group
        let activeGroup = this.formLayout[this.activeGroupIndex];
        if (activeGroup) {
          activeGroup[propertiesField] = e;
          this.model[propertiesField] = e;
        }
      }
    },
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const {
      activeTab,
      defaultGroups,
      defaultFields,
      formLayout,
      renderComponent,
      isDefaultFieldLoaded,
      keyToUpdateComponnets,
      activeFieldName,
      activeGroupIndex,
      model,
      propertiesType,
    } = storeToRefs(supplier_layouts_store);
    const { addMultipleForm } = supplier_layouts_store;

    const setting_store = useSettingStore();
    const { user_settings } = storeToRefs(setting_store);

    return {
      activeTab,
      defaultGroups,
      defaultFields,
      formLayout,
      renderComponent,
      isDefaultFieldLoaded,
      keyToUpdateComponnets,
      activeFieldName,
      activeGroupIndex,
      propertiesType,
      model,
      addMultipleForm,
      LabelStyle: ['inner', 'stack', 'outer', 'inline'],
      supplier_statuses,
      user_settings,
    };
  },
});
</script>

