<template>
  <div class="add-group-bar highlighted-back">
    <q-icon
      name="add"
      size="20px"
      class="cursor-pointer"
      @click="addGroup()"
    >
      <q-tooltip>{{ $t('add_step') }}</q-tooltip>
    </q-icon>
  </div>
  <div class="full-width" v-if="renderComponent">
    <div
      key="reRenderOnGroupChange"
      class="right-content-height scrolle-y"
      id="field_scrolle_2"
      style="
        min-height: 200px;
        height: calc(100vh - 230px);
        max-height: calc(100vh - 230px);
      "
    >
      <div class="full-width">
        <template
          v-for="(groupObj, groupIndex) in formLayout"
          :key="`div-${groupIndex}`"
        >
          <div
            :id="`div-${groupIndex}`"
            class="section-block dashed-border q-mb-md q-pa-sm"
          >
            <div class="q-pt-sm q-pb-sm">
              <div class="row cursor-move">
                <div class="col-sm-4 col-md-4 col-lg-4 q-pr-sm">
                  <q-input
                    outlined
                    dense
                    v-model="groupObj.name"
                    :label="$t('name')"
                    @click="inputClicked(groupObj, Number(groupIndex), 'group')"
                  />
                </div>
                <div class="col-sm-4 col-md-4 col-lg-4"></div>
                <div class="col-sm-4 col-md-4 col-lg-4">
                  <q-btn
                    outline
                    round
                    size="sm"
                    color="red-5"
                    icon="delete"
                    class="h-m-5 float-right"
                    @click="deleteSection(Number(groupIndex))"
                  >
                    <q-tooltip style="white-space: nowrap">{{
                      $t('delete_step')
                    }}</q-tooltip>
                  </q-btn>

                  <q-btn
                    outline
                    round
                    size="sm"
                    color="primary"
                    icon="move_up"
                    class="h-m-5 float-right"
                    @click="moveGroupUp($event, Number(groupIndex))"
                  >
                    <q-tooltip>{{ $t('move_up') }}</q-tooltip>
                  </q-btn>

                  <q-btn
                    outline
                    round
                    size="sm"
                    color="primary"
                    icon="move_down"
                    class="h-m-5 float-right"
                    @click="moveGroupDown($event, Number(groupIndex))"
                  >
                    <q-tooltip>{{ $t('move_down') }}</q-tooltip>
                  </q-btn>
                </div>
              </div>
            </div>
            <div class="full-width meta" v-if="isDefaultFieldLoaded">
              <draggable
                v-model="groupObj.rows"
                class="dragArea row"
                item-key="name"
                :group="{ name: 'formbuilder', pull: false, put: true }"
                :sort="true"
                ghost-class="sortable__ghost"
                @change="(e: any) => itemAdded(e, Number(groupIndex))"
              >
                <template
                  v-for="(element, index) in groupObj.rows"
                  :key="index"
                >
                  <div
                    v-bind="element"
                    @click="inputClicked(element, Number(groupIndex), 'field')"
                    class="cursor-move"
                    :class="[
                      element.name == activeFieldName
                        ? 'is--active  dashed-border'
                        : ' ',
                      element.is_hidden || element.isHidden ? 'field-container-hidden' : ''
                    ]"
                  >
                    <!-- Hidden field indicator badge with text -->
                    <div
                      v-if="element.is_hidden || element.isHidden"
                      class="hidden-field-badge-large"
                    >
                      <div class="flex items-center">
                        <q-icon
                          name="visibility_off"
                          size="sm"
                          color="white"
                          class="q-mr-xs"
                        />
                        <span class="text-caption text-white text-weight-bold">HIDDEN</span>
                      </div>
                      <q-tooltip>
                        <div class="text-weight-bold q-mb-xs">{{ $t('warning_field_globally_hidden') }}</div>
                        <div>{{ $t('hidden_field_explanation') }}</div>
                      </q-tooltip>
                    </div>
                    <Field
                      :meta_field="element"
                      :readonly="
                        element.type === 'file' ||
                        element.type === 'FILE' ||
                        element.is_hidden === true
                          ? true
                          : element.readonly
                      "
                      :key="element.name"
                      :model-value="element.default_value"
                      v-if="renderComponent"
                    />
                    <div
                      class="full-width q-pa-xs height-24"
                      v-if="element.name === activeFieldName"
                    >
                      <q-btn
                        flat
                        dense
                        class="float-right delete-ele"
                        @click="removeField($event, Number(groupIndex))"
                      >
                        <Icon icon="mdi:delete-outline" class="size-4" />
                        <q-tooltip>{{ $t('delete') }}</q-tooltip>
                      </q-btn>
                    </div>
                  </div>
                </template>
              </draggable>
            </div>
          </div>
        </template>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';
import { uid } from 'quasar';
import Field from 'src/supplier/components/dynamic/form/Field.vue';
import { useSupplierLayoutsStore } from 'src/store/main';
import { VueDraggableNext } from 'vue-draggable-next';

export default defineComponent({
  el: 'supplier_fields_designer',
  components: {
    draggable: VueDraggableNext,
    Field,
  },
  mounted: function () {
    // document.addEventListener('element_click',  this.triggerFieldFocus);
  },
  props: {
    isPanelSection: {
      type: Boolean,
      default: false,
    },
  },
  watch: {},
  data() {
    return {
      reRenderOnGroupChange: ref(0),
    };
  },
  setup() {
    const supplier_layouts_store = useSupplierLayoutsStore();
    const {
      activeTab,
      defaultGroups,
      defaultFields,
      formLayout,
      isDefaultFieldLoaded,
      keyToUpdateComponnets,
      activeFieldName,
      docType,
      allowAreaSelection,
      renderComponent,
      activeGroupIndex,
      propertiesType,
      model,
    } = storeToRefs(supplier_layouts_store);
    const actionButton = () => '<i class="q-icon material-icons">remove</i>';

    return {
      activeTab,
      defaultGroups,
      defaultFields,
      formLayout,
      isDefaultFieldLoaded,
      keyToUpdateComponnets,
      activeFieldName,
      docType,
      allowAreaSelection,
      renderComponent,
      activeGroupIndex,
      propertiesType,
      model,
      actionButton,
    };
  },
  methods: {
    moveGroupUp(e: any, groupIndex: number) {
      if (groupIndex == 0) {
        return;
      }
      const insertOn = groupIndex - 1;
      const item = JSON.parse(JSON.stringify(this.formLayout[groupIndex]));
      this.formLayout.splice(groupIndex, 1);
      this.formLayout.splice(insertOn, 0, item);
      this.reRenderOnGroupChange++;

      this.$nextTick(function () {
        let elementId = 'div-' + insertOn;
        document.getElementById(elementId)!.scrollIntoView();
      });
    },
    moveGroupDown(e: any, groupIndex: number) {
      if (this.formLayout.length == groupIndex) {
        return;
      }
      const insertOn = groupIndex + 1;
      const item = JSON.parse(JSON.stringify(this.formLayout[groupIndex]));
      this.formLayout.splice(groupIndex, 1);
      this.formLayout.splice(groupIndex + 1, 0, item);
      this.reRenderOnGroupChange++;

      this.$nextTick(function () {
        let elementId = 'div-' + insertOn;
        document.getElementById(elementId)!.scrollIntoView();
      });
    },
    deleteSection(groupIndex: number) {
      this.activeTab = 'form_elements';
      this.activeFieldName = '';

      this.$nextTick(function () {
        this.formLayout.splice(groupIndex, 1);
        this.reRenderOnGroupChange++;
      });
    },
    itemAdded(e: any, groupIndex: number) {
      let newSection = e.added.element;
      if (!newSection.class) {
        newSection.class = 'col-6';
        // newSection.default_value = newSection.calculation_formula
        if (!newSection.type) newSection.type = newSection.field_type;
        if (!newSection.name) newSection.name = uid();
        if (!newSection.design) newSection.design = 'outlined';
        if (!newSection.default) newSection.is_default = true;
        if (!newSection.label) newSection.label = newSection.title;
        if (!newSection.readonly) newSection.readonly = newSection.is_readonly;
        if (!newSection.required) newSection.required = newSection.is_required;
      }

      this.inputClicked(newSection, groupIndex, 'field');
      this.keyToUpdateComponnets++;
      if (!newSection.hasOwnProperty('rows')) {
        return;
      }
      this.formLayout.pop();
      this.formLayout.push(newSection);
    },
    removeField(e: any, groupIndex: number) {
      e.stopPropagation();

      this.formLayout[groupIndex].rows = this.formLayout[
        groupIndex
      ].rows.filter((item: any) => item.name !== this.activeFieldName);
      this.activeFieldName = '';
      this.activeTab = 'form_elements';
    },
    inputClicked(element: any, groupIndex: number, clickOnGroup: string) {
      if (groupIndex !== undefined && groupIndex !== null) {
        this.activeGroupIndex = groupIndex;
      }
      this.propertiesType = clickOnGroup;
      if (clickOnGroup === 'group') {
        const item = this.formLayout[groupIndex];
        this.model = item;
        this.activeFieldName = item.name;
      } else {
        this.activeFieldName = element.name;
        this.model = element;
      }
      this.activeTab = 'element_properties';
    },
    addGroup() {
      const group = {
        fieldType: formBuilderInputTypes.GROUP,
        name: '',
        title: '',
        group_key: '',
        icon: 'person',
        is_panel_section_group: this.isPanelSection,
        elementWidth: 100,
        height: 100,
        is_stcky_group: false,
        short_cut_key_1: '',
        short_cut_key_2: '',
        rows: [],
      };

      this.formLayout.push(group);
    },
  },
});
</script>

